  function materialForm(recordId=null){const r=state.records.find(r=>r.id===recordId),roles=r?state.roles.filter(x=>r.roleIds.includes(x.id)):state.roles;modal('登记材料库存',`<div class="form-grid">${field('name','材料名称','','text','','required')}${field('itemId','物品 ID（可留空）','')}${field('server','材料区服',state.roles.find(x=>x.id===ui.role)?.server||'','text','未知留空；明确归属角色时可采用该角色区服。')}${fnum('quantity','本次获得数量',1,'','min="0.000001" step="any" required')}${field('date','获得日期',r?.date||today,'date','','required')}${select('roleId','库存归属',[['','整队 / 未分配'],...roles.map(r=>[r.id,r.name])],'')}${select('tradable','交易属性',[['true','可交易'],['false','不可交易']],'true')}${field('unitPrice','参考单价（G，可留空）','','number','','min="0" step="any"')}${field('priceDate','报价日期',today,'date')}${field('priceSource','参考价来源','手工报价','text')}${field('source','来源 / 掉落依据',r?.taskName||'手工','text','','required')}<p class="panel-sub full">获得库存不生成金币收入；与执行关联时，后续出售归入该任务。未知价格保留为空。</p></div>`,fd=>commit(()=>{state.materials??=[];state.materials.push({id:M.id('material'),recordId:r?.id||null,roleId:fd.get('roleId')||null,name:fd.get('name').trim(),itemId:fd.get('itemId').trim(),server:fd.get('server').trim()||state.roles.find(r=>r.id===fd.get('roleId'))?.server||'',pricingMode:'manual',priceSource:fd.get('priceSource').trim(),priceValidForHours:72,quantity:M.number(fd.get('quantity'),'材料数量',{min:.000001}),date:fd.get('date'),tradable:fd.get('tradable')==='true',unitPrice:fd.get('unitPrice')===''?null:M.number(fd.get('unitPrice'),'参考价'),priceDate:fd.get('unitPrice')===''?null:fd.get('priceDate'),source:fd.get('source')});},'材料库存已保存，未计入收入'));}
  function materialPriceForm(id){const m=state.materials.find(m=>m.id===id),quotes=(state.priceQuotes||[]).filter(q=>q.kind==='material');modal('更新材料报价',`<div class="form-grid">${field('itemId','物品 ID（可留空）',m.itemId||'')}${field('server','材料区服',ROI.serverFor(state,m),'text','报价严格匹配此区服与物品，不混用其他服务器。')}${select('pricingMode','库存计价方式',[['manual','手工单价'],['latest','最新同区服 / 同物品报价'],['locked','锁定一条报价快照']],m.pricingMode||'manual')}${select('priceQuoteId','锁定快照（仅锁定模式使用）',[['','选择报价'],...quotes.map(q=>[q.id,q.name+' · '+(q.server||'未知区服')+' · '+beijingLocal(q.observedAt).replace('T',' ')])],m.priceQuoteId||'')}${field('unitPrice','参考单价（G，留空表示未知）',m.unitPrice??'','number','','min="0" step="any"')}${field('priceDate','报价日期',m.priceDate||today,'date','','required')}${field('priceSource','手工价格来源',m.priceSource||'手工报价','text')}${fnum('priceValidForHours','手工参考有效小时',m.priceValidForHours??72,'','min="0.000001" max="8760" step="any" required')}<p class="panel-sub full">最新 / 锁定模式采用价格档案中的来源和时点。只更新估值参数，历史成交收入与材料数量保持原值。</p></div>`,fd=>commit(()=>{const m=state.materials.find(m=>m.id===id);Object.assign(m,{itemId:fd.get('itemId').trim(),server:fd.get('server').trim(),pricingMode:fd.get('pricingMode'),priceQuoteId:fd.get('priceQuoteId')||null,unitPrice:fd.get('unitPrice')===''?null:M.number(fd.get('unitPrice'),'参考价'),priceDate:fd.get('unitPrice')===''?null:fd.get('priceDate'),priceSource:fd.get('priceSource').trim(),priceValidForHours:M.number(fd.get('priceValidForHours'),'参考有效小时',{min:.000001,max:8760}),updatedAt:new Date().toISOString()});},'材料计价参数已更新，成交历史未改写'));}
  function materialSaleForm(id){const m=state.materials.find(m=>m.id===id),r=state.records.find(r=>r.id===m.recordId),roles=r?state.roles.filter(x=>r.roleIds.includes(x.id)):state.roles;modal('登记材料实际出售',`<div class="form-grid">${field('date','成交日期',today,'date','','required')}${fnum('quantity','出售数量',Daily.inventory(state,m).left,'','min="0.000001" step="any" required')}${fnum('unitGold','实际成交单价（G）',m.unitPrice??0)}${fnum('feeGold','本次交易费用（G）',0)}${select('roleId','金币归属',m.roleId?[[m.roleId,state.roles.find(r=>r.id===m.roleId)?.name]]:[['','整队 / 未分配'],...roles.map(r=>[r.id,r.name])],m.roleId||'')}${field('eventKey','成交凭据编号','','text','','required')}${field('note','成交依据 / 备注','','text')}<p class="panel-sub full">按数量 × 实际单价 − 费用确认金币收入，同时扣减库存；不生成人民币兑现记录。</p></div>`,fd=>commit(()=>Daily.sale(state,{id:M.id('sale'),materialId:id,date:fd.get('date'),quantity:M.number(fd.get('quantity'),'出售数量',{min:.000001}),unitGold:M.number(fd.get('unitGold'),'成交价'),feeGold:M.number(fd.get('feeGold'),'交易费'),roleId:fd.get('roleId')||null,eventKey:fd.get('eventKey').trim(),note:fd.get('note')}),'材料出售已计账，库存已扣减'));}
