    if(plan){$('#f-taskId').disabled=true;$('#f-taskId').insertAdjacentHTML('afterend',`<input type="hidden" name="taskId" value="${t.id}">`);}else $('#f-taskId').addEventListener('change',e=>recordForm(null,e.target.value));
