  function sourceArchivePanel(){return `<section class="card mt">${head('导入来源档案','保留原工作表、单元格地址、公式与未映射状态；不执行公式')}${(state.sourceArchives||[]).length?table(['来源','原表','待确认','操作'],state.sourceArchives.map(x=>`<tr><td>${esc(x.name)}<small>${x.date}</small></td><td>${x.files?.length?x.files.length+' 个文件':x.book?x.book.sheets.length+' 张':(x.counts?.roles||0)+' 个角色'}</td><td>${x.issues?.length||0} 项</td><td>${button('查看待确认','source-issues','small',`data-id="${x.id}"`)}${button('导出原始归档','source-export','small',`data-id="${x.id}"`)}</td></tr>`)):empty('暂无来源归档')}</section>`;}
  async function importFile(file){
    if(!file)return;
    const chooser=$('#import-file');if(chooser)chooser.disabled=true;toast('正在读取并校验 '+file.name+'…');
    try{
      if(file.size>10*1024*1024)throw new Error('文件超过 10 MB，请拆分导入');
      const isXlsx=file.name.toLowerCase().endsWith('.xlsx'),migration=isXlsx?Importer.migrate(await Importer.readXLSX(await file.arrayBuffer(),file.name),state):null,text=isXlsx?'':await file.text(),parsed=migration?migration.incoming:file.name.toLowerCase().endsWith('.csv')?parseCSV(text):JSON.parse(text),archives=parsed?.storeVersion!==undefined?Store.validate(parsed):null;
      const incoming=archives?(archives.active||M.blank()):M.validateState(parsed),preview=M.merge(state,incoming),isEmpty=!Store.hasData(state);
      previewImport={incoming,name:file.name,archives};
      modal('导入预览 · '+esc(file.name),`${migration?`<p class="panel-sub mb">识别 ${migration.counts.roles} 个角色、${migration.incoming.progress.length} 条周期状态、${migration.counts.balances} 条总级余额；${migration.counts.archivedSheets} 张原表完整归档。已有 Excel 角色档案保持当前值；任务收益、工资、耗时没有从完成标记推断。</p><details class="mb"><summary>待确认 / 未映射 ${migration.issues.length} 项（保留原文）</summary><div class="pad">${migration.issues.map(x=>`<p>${esc(x)}</p>`).join('')||'无'}</div></details>`:''}<p class="muted mb">已验证版本、ID、账号归属与计算参数。源文件保持原样。</p><div class="list-detail"><div><span>将新增记录（合并）</span><b class="success">${preview.stats.added}</b></div><div><span>将更新记录（合并）</span><b>${preview.stats.updated}</b></div><div><span>重复 / 不可覆盖旧记录</span><b>${preview.stats.skipped+preview.stats.old}</b></div><div><span>来源数据性质</span><b>${incoming.dataKind==='simulated'?'示例 / 模拟':'手工 / 导入'}</b></div><div><span>账号 / 角色 / 任务</span><b>${incoming.accounts.length} / ${incoming.roles.length} / ${incoming.tasks.length}</b></div>${archives?`<div><span>包含日期档案</span><b>${archives.snapshots.length} 份</b></div>`:''}</div><div class="mt">${select('importMode','导入方式',[['merge','合并到当前工作空间'],['replace','替换当前工作空间（完整恢复文件）']],'merge')}</div><label class="mt"><input type="checkbox" name="applyConfig" ${isEmpty?'checked':''}> 合并时同时应用文件中的全局参数</label><div class="form-preview mt">替换会完整恢复文件参数和数据，保留其他日期档案。合并时，同 ID 金融事件不改写；没有更新时点的配置保留当前值。<br>日期档案会一并导入；相同档案 ID 只接纳较新的快照。确认后可立即撤销。</div>`,fd=>{
        const item=previewImport,wasSetup=ui.setup;
        commit(()=>{
          const existingRoleIds=new Set(state.roles.map(r=>r.id)),replace=fd.get('importMode')==='replace',merged=M.merge(state,item.incoming),empty=!Store.hasData(state);
          state=M.freezeHistory(M.upgradeState(replace?structuredClone(item.incoming):merged.next));
          if(replace||empty||fd.get('applyConfig'))state.config={...item.incoming.config};
          if(replace||empty)state.dataKind=item.incoming.dataKind;else if(item.incoming.dataKind==='simulated'&&merged.stats.added)state.dataKind='simulated';
          if(!replace&&(merged.stats.added||merged.stats.updated))state.imports.push({id:M.id('import'),name:item.name,date:M.dateKey(),stats:merged.stats});
          Ops.ensureDefaults(state);if(!replace)for(const r of state.roles.filter(r=>!existingRoleIds.has(r.id)))Ops.syncRole(state,r);
          if(item.archives)dataStore=Store.mergeArchives(dataStore,item.archives);
          clearScope();
        },'数据导入已完成，可立即撤销');
        if(wasSetup){ui.setup=!state.accounts.length&&!state.roles.length;ui.setupStep=0;ui.page='overview';render();}
      },'确认导入');
    }catch(e){toast('导入失败，既有数据未修改：'+e.message);const box=$('#import-preview');if(box)box.innerHTML=`<p class="error">✕ ${esc(e.message)}；当前数据未修改。</p>`;}
    finally{const input=$('#import-file');if(input){input.value='';input.disabled=false;}}
  }
  function generatePlan(taskId){
    if(ui.generated?.taskId===taskId&&ui.generated.lockedBatches?.length)throw new Error('当前方案包含锁定队伍，请先解锁后重新生成');
    const t={...M.planningTask(M.taskForVersion(state,state.tasks.find(x=>x.id===taskId))),raidMode:ui.raidMode},when=ui.planStartTime?ui.taskDate+'T'+ui.planStartTime+':00+08:00':ui.taskDate,roles=M.availableRoles(state,t,when,scope(),ui.replacingPlanId);let result;
    if(t.partyRule==='raid10'&&ui.routeTaskIds.filter(id=>id!==t.id).length){result=M.routePlan(state,[t.id,...ui.routeTaskIds.filter(id=>id!==t.id)],when,ui.locks,scope(),ui.replacingPlanId,{fullRaid:true,raidMode:ui.raidMode});}
    else if(t.type==='team'){const g=M.teamCandidates(t,roles,ui.locks,state.config.concurrency);result={...M.calculateTeam(t,g.teams,M.pricingConfig(state)),reasons:g.reasons,parties:g.parties||[],unassigned:g.unassigned||[],powerBasis:g.powerBasis};}
    else{const all=[],counts=roles.map(r=>({r,n:M.availableCount(state,t,r,when,ui.replacingPlanId)}));for(let i=0;i<Math.max(0,...counts.map(x=>x.n));i++)all.push(M.calculateRole({...t,prepare:i?0:t.prepare,otherCost:i?0:t.otherCost},counts.filter(x=>x.n>i).map(x=>x.r),M.pricingConfig(state),1));result={...M.sum(all,state.config),batches:all.flatMap(x=>x.batches),parties:all.flatMap(x=>x.parties||[]),reasons:[...new Set(all.flatMap(x=>x.reasons||[]))],unassigned:all.flatMap(x=>x.unassigned||[])};}
    if(t.type==='role')result={...result,...M.optimizeTaskBatches(t,result.batches,state.config.concurrency,result.parties)};
    if(!result.taskResults)result=M.pricePrediction(state,t,result,when);
    ui.planTask=t.id;ui.generated={taskId:t.id,raidMode:t.partyRule==='raid10'?ui.raidMode:undefined,fillCompanionSlots:t.partyRule==='raid10',date:ui.taskDate,startedAt:ui.planStartTime?when:null,result,routeTaskIds:result.taskResults?.map(x=>x.task.id)};render();
  }
  function scheduleEdit(t,date){modal('调整该周期目标 · '+esc(t.name),`<p class="muted mb">${date} · 周期 ${M.cycle(t,date)}。按角色覆盖目标；目标减少会同步改变预测与账号用量。完成历史保留。</p><div class="form-grid">${fnum('target','所选角色本周期目标',t.target,'设为 0 时不再贡献预测。','min="0" step="1" required')}${roleChecks(t.roleIds,'roles',true)}</div>`,fd=>commit(()=>{const target=M.number(fd.get('target'),'目标',{integer:true});for(const id of fd.getAll('roles')){if(!t.roleIds.includes(id))throw new Error('只能调整已分配角色的目标');const r=state.roles.find(r=>r.id===id),p=M.getProgress(state,t,r,date);updateProgress(t,r,date,p?.status||'planned',p?.completed||0,target);}ui.generated=null;},'周期目标已更新'));}
